azureLogAnalytics.query:
declare query_parameters(e2e:string = '${e2e}');
let ivr = union AppDependencies, AppRequests, AppTraces | where tostring(Properties['e2e.call_id']) == e2e | project TimestampUtc = TimeGenerated, Boundary='IVR', Source=ItemType, Operation=coalesce(column_ifexists('Name',''), column_ifexists('Message','')), CallConnectionId=tostring(Properties['acs.call_connection_id']), ContextId=tostring(Properties['call.context_id']);
let connIds = toscalar(ivr | where isnotempty(CallConnectionId) | summarize make_set(CallConnectionId));
let ctxId = toscalar(ivr | where isnotempty(ContextId) | take 1 | project ContextId);
let acs = ACSCallAutomationIncomingOperations | where CallConnectionId in (connIds) | project TimestampUtc = TimeGenerated, Boundary='ACS', Source='CallAutomation', Operation=OperationName, CallConnectionId, ContextId='';
let d365 = AppTraces | extend cd=parse_json(Properties) | where tostring(cd['cc_contextId'])==ctxId and isnotempty(ctxId) | project TimestampUtc = TimeGenerated, Boundary='D365', Source='ConversationDiagnostics', Operation=tostring(cd['powerplatform.analytics.subscenario']), CallConnectionId='', ContextId=tostring(cd['cc_contextId']);
union ivr, acs, d365 | order by TimestampUtc asc

let acsTransfers = ACSCallAutomationIncomingOperations | where OperationName has_any ('Transfer','CallTransferAccepted','CallTransferFailed') | summarize TransfersAccepted=countif(OperationName has 'Accepted' or ResultType=='Succeeded'), TransfersFailed=countif(OperationName has 'Failed' or ResultType=='Failed');
let d365 = AppTraces | extend cd=parse_json(Properties) | where tostring(cd['powerplatform.analytics.subscenario']) has_any ('Classification','RouteToQueue') | summarize D365ConversationsCreated=dcount(tostring(cd['cc_contextId']));
acsTransfers | extend d=1 | join kind=fullouter (d365 | extend d=1) on d | project TransfersAccepted, TransfersFailed, D365ConversationsCreated, HandoffGap = TransfersAccepted - D365ConversationsCreated
